Aquí te dejo un ejemplo de cómo implementar este programa en C++:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string word; // palabra a buscar
    int count = 0; // contador de apariciones

    // Solicitamos la palabra a buscar al usuario
    cout << "Introduzca la palabra a buscar: ";
    cin >> word;

    // Abrimos el archivo para lectura
    ifstream file("archivo.txt");

    if (!file.is_open()) {
        cerr << "Error al abrir el archivo." << endl;
        return 1;
    }

    // Leemos línea por línea el contenido del archivo
    string line;
    while (getline(file, line)) {
        // Convertimos a mayúsculas para evitar distinción entre mayúsculas y minúsculas
        transform(line.begin(), line.end(), line.begin(), ::toupper);

        // Contamos el número de apariciones de la palabra en la línea
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    // Cerramos el archivo
    file.close();

    // Imprimimos el resultado
    cout << "El número de apariciones de \"" << word << "\" en el archivo es: " << count << endl;

    return 0;
}
```

Este programa lee el contenido del archivo de texto llamado "archivo.txt" línea por línea, convierte cada línea a mayúsculas para evitar distinción entre mayúsculas y minúsculas, y cuenta el número de apariciones de la palabra especificada por el usuario.

Recuerda que debes reemplazar "archivo.txt" por el nombre del archivo de texto que deseas leer. También debes tener en cuenta que este programa no realiza ninguna validación de entrada, por lo que es importante que el usuario ingrese una palabra válida y que el archivo esté disponible en el directorio actual.
